package api

import (
	"context"
	"encoding/json"
	"errors"
	"fmt"
	"net/http"
	"os"
	"strconv"
	"strings"

	"github.com/kiry163/llmmeter/internal/pricing"
	"github.com/kiry163/llmmeter/internal/settings"
)

const (
	// maxBodyBytes bounds every configuration request body.
	maxBodyBytes = 1 << 20

	// gatewayKeyDisplayPrefix is the fixed prefix of keys generated by
	// secure.NewGatewayKey.
	gatewayKeyDisplayPrefix = "sk-local-"
)

// decodeJSON decodes the request body into v, answering 400 on malformed
// input.
func decodeJSON(w http.ResponseWriter, r *http.Request, v any) bool {
	dec := json.NewDecoder(http.MaxBytesReader(w, r.Body, maxBodyBytes))
	if err := dec.Decode(v); err != nil {
		writeAPIError(w, http.StatusBadRequest, codeValidation, "invalid JSON body")
		return false
	}
	return true
}

// requireSetup answers 409 while first-run setup is incomplete. Settings
// writes before setup would leave rows behind that make Repo.Setup fail or
// report "already set up", so they are refused outright.
func (s *Server) requireSetup(w http.ResponseWriter) bool {
	if snap := s.repo.Snapshot(); snap == nil || !snap.SetupDone {
		writeAPIError(w, http.StatusConflict, codeConflict, "setup required")
		return false
	}
	return true
}

// pathID parses the {id} path value, answering 400 on malformed input.
func pathID(w http.ResponseWriter, r *http.Request) (int64, bool) {
	id, err := strconv.ParseInt(r.PathValue("id"), 10, 64)
	if err != nil || id <= 0 {
		writeAPIErrorFields(w, http.StatusBadRequest, codeValidation, "invalid model id",
			map[string]string{"id": "must be a positive integer"})
		return 0, false
	}
	return id, true
}

// writeRepoError maps a settings repository error onto the API envelope.
func writeRepoError(w http.ResponseWriter, err error) {
	var ve *settings.ValidationError
	switch {
	case errors.As(err, &ve):
		writeAPIErrorFields(w, http.StatusBadRequest, codeValidation, ve.Error(), ve.Fields)
	case errors.Is(err, settings.ErrNotFound):
		writeAPIError(w, http.StatusNotFound, codeNotFound, "not found")
	case errors.Is(err, settings.ErrAlreadySetup):
		writeAPIError(w, http.StatusConflict, codeConflict, "setup already completed")
	case errors.Is(err, settings.ErrConflict):
		writeAPIError(w, http.StatusConflict, codeConflict, "name already exists")
	default:
		writeInternal(w, err)
	}
}

// --- setup -----------------------------------------------------------------

type setupUpstream struct {
	BaseURL string `json:"baseUrl"`
	APIKey  string `json:"apiKey"`
}

type setupRequest struct {
	Upstream      setupUpstream `json:"upstream"`
	Timezone      string        `json:"timezone"`
	AdminPassword string        `json:"adminPassword"`
}

type gatewayKeyResponse struct {
	GatewayKey string `json:"gatewayKey"`
}

// setup performs first-run initialization. It is available only before setup
// has completed and only from the local machine.
func (s *Server) setup(w http.ResponseWriter, r *http.Request) {
	if snap := s.repo.Snapshot(); snap != nil && snap.SetupDone {
		writeAPIError(w, http.StatusConflict, codeConflict, "setup already completed")
		return
	}
	var in setupRequest
	if !decodeJSON(w, r, &in) {
		return
	}
	key, err := s.repo.Setup(r.Context(), settings.SetupInput{
		Upstream: settings.Upstream{
			BaseURL: in.Upstream.BaseURL,
			APIKey:  in.Upstream.APIKey,
		},
		Timezone:      in.Timezone,
		AdminPassword: in.AdminPassword,
	})
	if err != nil {
		writeRepoError(w, err)
		return
	}
	s.catalog.invalidate()
	if in.AdminPassword != "" {
		s.auth.Issue(w)
	}
	writeJSON(w, http.StatusOK, gatewayKeyResponse{GatewayKey: key})
}

// --- models ----------------------------------------------------------------

type windowJSON struct {
	ID                int64    `json:"id"`
	Label             string   `json:"label"`
	DaysMask          uint8    `json:"daysMask"`
	StartMinute       int      `json:"startMinute"`
	EndMinute         int      `json:"endMinute"`
	InputPerMTok      *float64 `json:"inputPerMTok"`
	OutputPerMTok     *float64 `json:"outputPerMTok"`
	CacheReadPerMTok  *float64 `json:"cacheReadPerMTok"`
	CacheWritePerMTok *float64 `json:"cacheWritePerMTok"`
	ReasoningPerMTok  *float64 `json:"reasoningPerMTok"`
}

type modelJSON struct {
	ID                int64        `json:"id"`
	Name              string       `json:"name"`
	InputPerMTok      float64      `json:"inputPerMTok"`
	OutputPerMTok     float64      `json:"outputPerMTok"`
	CacheReadPerMTok  float64      `json:"cacheReadPerMTok"`
	CacheWritePerMTok float64      `json:"cacheWritePerMTok"`
	ReasoningPerMTok  *float64     `json:"reasoningPerMTok"`
	Windows           []windowJSON `json:"windows"`
}

type modelsResponse struct {
	Models []modelJSON `json:"models"`
}

func toModelJSON(m pricing.Model) modelJSON {
	wins := make([]windowJSON, 0, len(m.Windows))
	for _, win := range m.Windows {
		wins = append(wins, windowJSON{
			ID:                win.ID,
			Label:             win.Label,
			DaysMask:          win.DaysMask,
			StartMinute:       win.StartMinute,
			EndMinute:         win.EndMinute,
			InputPerMTok:      win.Input,
			OutputPerMTok:     win.Output,
			CacheReadPerMTok:  win.CacheRead,
			CacheWritePerMTok: win.CacheWrite,
			ReasoningPerMTok:  win.Reasoning,
		})
	}
	return modelJSON{
		ID:                m.ID,
		Name:              m.Name,
		InputPerMTok:      m.Input,
		OutputPerMTok:     m.Output,
		CacheReadPerMTok:  m.CacheRead,
		CacheWritePerMTok: m.CacheWrite,
		ReasoningPerMTok:  m.Reasoning,
		Windows:           wins,
	}
}

// modelByID returns the current model with its windows.
func (s *Server) modelByID(ctx context.Context, id int64) (pricing.Model, error) {
	models, err := s.repo.Models(ctx)
	if err != nil {
		return pricing.Model{}, err
	}
	for _, m := range models {
		if m.ID == id {
			return m, nil
		}
	}
	return pricing.Model{}, settings.ErrNotFound
}

func (s *Server) listModels(w http.ResponseWriter, r *http.Request) {
	models, err := s.repo.Models(r.Context())
	if err != nil {
		writeInternal(w, err)
		return
	}
	out := modelsResponse{Models: make([]modelJSON, 0, len(models))}
	for _, m := range models {
		out.Models = append(out.Models, toModelJSON(m))
	}
	writeJSON(w, http.StatusOK, out)
}

type modelCreateRequest struct {
	Name              string   `json:"name"`
	InputPerMTok      float64  `json:"inputPerMTok"`
	OutputPerMTok     float64  `json:"outputPerMTok"`
	CacheReadPerMTok  float64  `json:"cacheReadPerMTok"`
	CacheWritePerMTok float64  `json:"cacheWritePerMTok"`
	ReasoningPerMTok  *float64 `json:"reasoningPerMTok"`
}

func (s *Server) createModel(w http.ResponseWriter, r *http.Request) {
	var in modelCreateRequest
	if !decodeJSON(w, r, &in) {
		return
	}
	model, err := s.repo.CreateModel(r.Context(), settings.ModelInput{
		Name:       in.Name,
		Input:      in.InputPerMTok,
		Output:     in.OutputPerMTok,
		CacheRead:  in.CacheReadPerMTok,
		CacheWrite: in.CacheWritePerMTok,
		Reasoning:  in.ReasoningPerMTok,
	})
	if err != nil {
		writeRepoError(w, err)
		return
	}
	writeJSON(w, http.StatusCreated, toModelJSON(model))
}

// optionalFloat distinguishes an absent JSON field from an explicit null.
type optionalFloat struct {
	set   bool
	value *float64
}

func (o *optionalFloat) UnmarshalJSON(b []byte) error {
	o.set = true
	if string(b) == "null" {
		o.value = nil
		return nil
	}
	var v float64
	if err := json.Unmarshal(b, &v); err != nil {
		return err
	}
	o.value = &v
	return nil
}

type modelPatchRequest struct {
	Name              *string       `json:"name"`
	InputPerMTok      *float64      `json:"inputPerMTok"`
	OutputPerMTok     *float64      `json:"outputPerMTok"`
	CacheReadPerMTok  *float64      `json:"cacheReadPerMTok"`
	CacheWritePerMTok *float64      `json:"cacheWritePerMTok"`
	ReasoningPerMTok  optionalFloat `json:"reasoningPerMTok"`
}

func (s *Server) updateModel(w http.ResponseWriter, r *http.Request) {
	id, ok := pathID(w, r)
	if !ok {
		return
	}
	var in modelPatchRequest
	if !decodeJSON(w, r, &in) {
		return
	}
	patch := settings.ModelPatch{
		Name:       in.Name,
		Input:      in.InputPerMTok,
		Output:     in.OutputPerMTok,
		CacheRead:  in.CacheReadPerMTok,
		CacheWrite: in.CacheWritePerMTok,
	}
	if in.ReasoningPerMTok.set {
		patch.Reasoning = &in.ReasoningPerMTok.value
	}
	if err := s.repo.UpdateModel(r.Context(), id, patch); err != nil {
		writeRepoError(w, err)
		return
	}
	s.writeModel(w, r, id)
}

func (s *Server) deleteModel(w http.ResponseWriter, r *http.Request) {
	id, ok := pathID(w, r)
	if !ok {
		return
	}
	if err := s.repo.DeleteModel(r.Context(), id); err != nil {
		writeRepoError(w, err)
		return
	}
	w.WriteHeader(http.StatusNoContent)
}

type modelImportRequest struct {
	Names []string `json:"names"`
}

// importedModelJSON is the minimal shape returned for each created model.
type importedModelJSON struct {
	ID   int64  `json:"id"`
	Name string `json:"name"`
}

type modelImportResponse struct {
	Created []importedModelJSON `json:"created"`
	Skipped []string            `json:"skipped"`
}

// importModels creates the missing models of a batch with zero rates. Existing
// names are reported as skipped rather than modified.
func (s *Server) importModels(w http.ResponseWriter, r *http.Request) {
	var in modelImportRequest
	if !decodeJSON(w, r, &in) {
		return
	}
	created, skipped, err := s.repo.ImportModels(r.Context(), in.Names)
	if err != nil {
		writeRepoError(w, err)
		return
	}
	out := modelImportResponse{
		Created: make([]importedModelJSON, 0, len(created)),
		Skipped: skipped,
	}
	for _, m := range created {
		out.Created = append(out.Created, importedModelJSON{ID: m.ID, Name: m.Name})
	}
	writeJSON(w, http.StatusOK, out)
}

type windowInput struct {
	Label             string   `json:"label"`
	DaysMask          int      `json:"daysMask"`
	StartMinute       int      `json:"startMinute"`
	EndMinute         int      `json:"endMinute"`
	InputPerMTok      *float64 `json:"inputPerMTok"`
	OutputPerMTok     *float64 `json:"outputPerMTok"`
	CacheReadPerMTok  *float64 `json:"cacheReadPerMTok"`
	CacheWritePerMTok *float64 `json:"cacheWritePerMTok"`
	ReasoningPerMTok  *float64 `json:"reasoningPerMTok"`
}

type windowsRequest struct {
	Windows *[]windowInput `json:"windows"`
}

func (s *Server) replaceWindows(w http.ResponseWriter, r *http.Request) {
	id, ok := pathID(w, r)
	if !ok {
		return
	}
	var in windowsRequest
	if !decodeJSON(w, r, &in) {
		return
	}
	if in.Windows == nil {
		writeAPIErrorFields(w, http.StatusBadRequest, codeValidation, "invalid windows payload",
			map[string]string{"windows": "required"})
		return
	}
	wins := make([]pricing.Window, 0, len(*in.Windows))
	for _, win := range *in.Windows {
		mask := uint8(0)
		// Out-of-range masks become 0 so validateWindows reports them.
		if win.DaysMask >= 0 && win.DaysMask <= 255 {
			mask = uint8(win.DaysMask)
		}
		wins = append(wins, pricing.Window{
			Label:       win.Label,
			DaysMask:    mask,
			StartMinute: win.StartMinute,
			EndMinute:   win.EndMinute,
			Input:       win.InputPerMTok,
			Output:      win.OutputPerMTok,
			CacheRead:   win.CacheReadPerMTok,
			CacheWrite:  win.CacheWritePerMTok,
			Reasoning:   win.ReasoningPerMTok,
		})
	}
	if err := s.repo.ReplaceWindows(r.Context(), id, wins); err != nil {
		writeRepoError(w, err)
		return
	}
	s.writeModel(w, r, id)
}

// writeModel answers with the current state of model id.
func (s *Server) writeModel(w http.ResponseWriter, r *http.Request, id int64) {
	model, err := s.modelByID(r.Context(), id)
	if err != nil {
		writeRepoError(w, err)
		return
	}
	writeJSON(w, http.StatusOK, toModelJSON(model))
}

// --- settings --------------------------------------------------------------

// maskedSecret is the only shape in which a stored secret leaves the API.
type maskedSecret struct {
	Set   bool   `json:"set"`
	Last4 string `json:"last4"`
}

// maskedGatewayKey additionally names the key's fixed prefix.
type maskedGatewayKey struct {
	Set    bool   `json:"set"`
	Prefix string `json:"prefix"`
	Last4  string `json:"last4"`
}

type upstreamSettings struct {
	BaseURL string       `json:"baseUrl"`
	APIKey  maskedSecret `json:"apiKey"`
}

type settingsResponse struct {
	Upstream         upstreamSettings `json:"upstream"`
	Timezone         string           `json:"timezone"`
	RetentionDays    int              `json:"retentionDays"`
	GatewayKey       maskedGatewayKey `json:"gatewayKey"`
	AdminPasswordSet bool             `json:"adminPasswordSet"`
	Listen           string           `json:"listen"`
	DBPath           string           `json:"dbPath"`
	DBSizeBytes      int64            `json:"dbSizeBytes"`
	Version          string           `json:"version"`
}

// last4 returns the last four characters of secret, or "" when the secret is
// too short to mask.
func last4(secret string) string {
	if len(secret) <= 4 {
		return ""
	}
	return secret[len(secret)-4:]
}

// settingsView assembles the masked settings payload.
func (s *Server) settingsView() settingsResponse {
	var up settings.Upstream
	retention := 0
	adminSet := false
	gatewayKey := ""
	if snap := s.repo.Snapshot(); snap != nil {
		up = snap.Upstream
		retention = snap.RetentionDays
		adminSet = snap.AdminPasswordHash != ""
		gatewayKey = snap.GatewayKey
	}
	var size int64
	for _, suffix := range []string{"", "-wal", "-shm"} {
		if info, err := os.Stat(s.dbPath + suffix); err == nil && info.Mode().IsRegular() {
			size += info.Size()
		}
	}
	gw := maskedGatewayKey{}
	if gatewayKey != "" {
		gw = maskedGatewayKey{Set: true, Prefix: gatewayKeyDisplayPrefix, Last4: last4(gatewayKey)}
	}
	return settingsResponse{
		Upstream: upstreamSettings{
			BaseURL: up.BaseURL,
			APIKey:  maskedSecret{Set: up.APIKey != "", Last4: last4(up.APIKey)},
		},
		Timezone:         s.location().String(),
		RetentionDays:    retention,
		GatewayKey:       gw,
		AdminPasswordSet: adminSet,
		Listen:           s.listen,
		DBPath:           s.dbPath,
		DBSizeBytes:      size,
		Version:          s.version,
	}
}

func (s *Server) getSettings(w http.ResponseWriter, _ *http.Request) {
	writeJSON(w, http.StatusOK, s.settingsView())
}

type upstreamPatch struct {
	BaseURL *string `json:"baseUrl"`
	APIKey  *string `json:"apiKey"`
}

type settingsPatchRequest struct {
	Upstream        *upstreamPatch `json:"upstream"`
	Timezone        *string        `json:"timezone"`
	RetentionDays   *int           `json:"retentionDays"`
	CurrentPassword string         `json:"currentPassword"`
	NewPassword     string         `json:"newPassword"`
	ClearPassword   bool           `json:"clearPassword"`
}

func (s *Server) patchSettings(w http.ResponseWriter, r *http.Request) {
	if !s.requireSetup(w) {
		return
	}
	var in settingsPatchRequest
	if !decodeJSON(w, r, &in) {
		return
	}
	// Validate every field before changing anything, so an invalid payload
	// never leaves a password change behind.
	var patch settings.Patch
	if in.Upstream != nil {
		patch.BaseURL = in.Upstream.BaseURL
		patch.APIKey = in.Upstream.APIKey
	}
	patch.Timezone = in.Timezone
	patch.RetentionDays = in.RetentionDays

	// Clearing the password is only safe while listening on loopback: a
	// restart with a non-loopback listen and no password refuses to start.
	if in.ClearPassword && !LoopbackListen(s.listen) {
		writeAPIErrorFields(w, http.StatusBadRequest, codeValidation, "invalid settings",
			map[string]string{"clearPassword": "only allowed while listening on loopback"})
		return
	}
	var pw *settings.PasswordChange
	if in.NewPassword != "" || in.ClearPassword {
		pw = &settings.PasswordChange{
			Current: in.CurrentPassword,
			New:     in.NewPassword,
			Clear:   in.ClearPassword,
		}
	}
	// One repository call validates and commits the settings and the password
	// change in a single transaction, so a rejected field changes nothing.
	if err := s.repo.ApplyPatch(r.Context(), patch, pw); err != nil {
		writeRepoError(w, err)
		return
	}
	s.catalog.invalidate()
	writeJSON(w, http.StatusOK, s.settingsView())
}

func (s *Server) rotateGatewayKey(w http.ResponseWriter, r *http.Request) {
	if !s.requireSetup(w) {
		return
	}
	key, err := s.repo.RotateGatewayKey(r.Context())
	if err != nil {
		writeInternal(w, err)
		return
	}
	writeJSON(w, http.StatusOK, gatewayKeyResponse{GatewayKey: key})
}

// upstreamTestRoute authorizes the connectivity probe: loopback only before
// setup completes, a session afterwards.
func (s *Server) upstreamTestRoute(h http.HandlerFunc) http.Handler {
	session := s.auth.Require(h)
	loopback := s.auth.RequireLoopback(h)
	return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		if snap := s.repo.Snapshot(); snap == nil || !snap.SetupDone {
			loopback.ServeHTTP(w, r)
			return
		}
		session.ServeHTTP(w, r)
	})
}

// --- upstream probe --------------------------------------------------------

type upstreamTestRequest struct {
	BaseURL string `json:"baseUrl"`
	APIKey  string `json:"apiKey"`
}

type upstreamTestResponse struct {
	OK       bool   `json:"ok"`
	Status   int    `json:"status"`
	Endpoint string `json:"endpoint,omitempty"`
	Message  string `json:"message,omitempty"`
}

// upstreamTest checks that the configured upstream answers a models listing.
// It tries <base>/models first and, when that path is missing, <base>/v1/models
// (unless base already ends in /v1). The request carries no headers copied
// from the client; the resolved key is sent as a bearer token and is never
// echoed.
func (s *Server) upstreamTest(w http.ResponseWriter, r *http.Request) {
	var in upstreamTestRequest
	if !decodeJSON(w, r, &in) {
		return
	}
	base := strings.TrimRight(strings.TrimSpace(in.BaseURL), "/")
	if base == "" {
		writeAPIErrorFields(w, http.StatusBadRequest, codeValidation, "invalid upstream probe",
			map[string]string{"baseUrl": "required"})
		return
	}
	key := in.APIKey
	if key == "" {
		if snap := s.repo.Snapshot(); snap != nil {
			key = snap.Upstream.APIKey
		}
	}
	client := &http.Client{}
	endpoints := []string{"/models"}
	if !strings.HasSuffix(base, "/v1") {
		endpoints = append(endpoints, "/v1/models")
	}

	var resp *http.Response
	var endpoint string
	var err error
	for i, path := range endpoints {
		var req *http.Request
		req, err = http.NewRequestWithContext(r.Context(), http.MethodGet, base+path, nil)
		if err != nil {
			writeAPIErrorFields(w, http.StatusBadRequest, codeValidation, "invalid upstream probe",
				map[string]string{"baseUrl": "must be an http or https URL"})
			return
		}
		if key != "" {
			req.Header.Set("Authorization", "Bearer "+key)
		}
		resp, err = client.Do(req)
		if err != nil {
			break
		}
		endpoint = path
		// A missing /models endpoint is often an OpenAI-compatible server
		// that only exposes the versioned path; retry once before reporting.
		if (resp.StatusCode == http.StatusNotFound || resp.StatusCode == http.StatusMethodNotAllowed) &&
			i < len(endpoints)-1 {
			resp.Body.Close()
			continue
		}
		break
	}
	if err != nil {
		writeJSON(w, http.StatusBadGateway, upstreamTestResponse{OK: false, Message: err.Error()})
		return
	}
	resp.Body.Close()
	if resp.StatusCode == http.StatusOK {
		writeJSON(w, http.StatusOK, upstreamTestResponse{OK: true, Status: resp.StatusCode, Endpoint: endpoint})
		return
	}
	writeJSON(w, http.StatusBadGateway, upstreamTestResponse{
		OK:       false,
		Status:   resp.StatusCode,
		Endpoint: endpoint,
		Message:  fmt.Sprintf("upstream returned HTTP %d", resp.StatusCode),
	})
}
